pub fn to_string(
    scheme: &str,
    host: &str,
    port: i32,
    path: &str,
    query: &str,
    fragment: &str,
) -> String {
    let mut rendered = String::new();

    if !scheme.is_empty() {
        rendered.push_str(scheme);
        rendered.push_str("://");
        rendered.push_str(host);

        if port >= 0 {
            rendered.push(':');
            rendered.push_str(&port.to_string());
        }
    }

    rendered.push_str(path);

    if !query.is_empty() {
        rendered.push('?');
        rendered.push_str(query);
    }

    if !fragment.is_empty() {
        rendered.push('#');
        rendered.push_str(fragment);
    }

    rendered
}

