use super::{normalize, render};

pub struct URL {
    scheme: String,
    host: String,
    port: i32,
    path: String,
    query: String,
    fragment: String,
}

impl URL {
    pub fn from_components(
        scheme: String,
        host: String,
        port: i32,
        path: String,
        query: String,
        fragment: String,
    ) -> Self {
        Self {
            scheme: normalize::scheme(scheme),
            host,
            port: normalize::port(port),
            path: normalize::path(path),
            query,
            fragment,
        }
    }

    pub fn scheme(&self) -> &str {
        &self.scheme
    }

    pub fn host(&self) -> &str {
        &self.host
    }

    pub fn port(&self) -> i32 {
        self.port
    }

    pub fn path(&self) -> &str {
        &self.path
    }

    pub fn query(&self) -> &str {
        &self.query
    }

    pub fn fragment(&self) -> &str {
        &self.fragment
    }

    pub fn to_string(&self) -> String {
        render::to_string(
            &self.scheme,
            &self.host,
            self.port,
            &self.path,
            &self.query,
            &self.fragment,
        )
    }

    pub fn is_valid(&self) -> bool {
        normalize::is_valid(&self.host, &self.path)
    }
}

